DECLARE
    previous integration_inventory_source_mapping%ROWTYPE;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM integration_organization o
        JOIN integration_connection c ON c.organization_id = o.organization_id
        WHERE o.organization_id = NEW.organization_id
          AND c.connection_id = NEW.connection_id
          AND o.status = 'ACTIVE'
          AND c.status IN ('ACTIVE', 'SUSPENDED')
    ) THEN
        RAISE EXCEPTION 'inventory mapping scope unavailable';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM integration_inventory_source_balance e
        WHERE e.organization_id = NEW.organization_id
          AND e.connection_id = NEW.connection_id
          AND e.capability = NEW.capability
          AND e.input_progress_version = NEW.evidence_progress_version
          AND e.record_ordinal = NEW.evidence_record_ordinal
          AND e.source_item_ref = NEW.source_item_ref
          AND e.source_location_ref IS NOT DISTINCT FROM NEW.source_location_ref
          AND e.source_unit_code IS NOT DISTINCT FROM NEW.source_unit_code
    ) THEN
        RAISE EXCEPTION 'inventory mapping evidence unavailable';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM inventory_item_identity
        WHERE organization_id = NEW.organization_id
          AND identity_id = NEW.target_item_id AND state = 'ACTIVE'
    ) OR NOT EXISTS (
        SELECT 1 FROM inventory_unit_identity
        WHERE organization_id = NEW.organization_id
          AND identity_id = NEW.target_unit_id AND state = 'ACTIVE'
    ) OR (NEW.target_location_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM inventory_location_identity
        WHERE organization_id = NEW.organization_id
          AND identity_id = NEW.target_location_id AND state = 'ACTIVE'
    )) THEN
        RAISE EXCEPTION 'inventory mapping target unavailable';
    END IF;

    IF NEW.supersedes_decision_id IS NOT NULL THEN
        SELECT * INTO previous FROM integration_inventory_source_mapping
        WHERE organization_id = NEW.organization_id
          AND decision_id = NEW.supersedes_decision_id;
        IF NOT FOUND OR previous.connection_id <> NEW.connection_id
           OR previous.capability <> NEW.capability
           OR previous.source_item_ref <> NEW.source_item_ref
           OR previous.source_location_ref IS DISTINCT FROM NEW.source_location_ref
           OR previous.source_unit_code IS DISTINCT FROM NEW.source_unit_code
           OR previous.revision <> NEW.revision - 1 THEN
            RAISE EXCEPTION 'inventory mapping predecessor unavailable';
        END IF;
    END IF;
    RETURN NEW;
END;

DECLARE
    candidate integration_inventory_canonical_observation%ROWTYPE;
    mapping integration_inventory_source_mapping%ROWTYPE;
    root integration_inventory_source_mapping%ROWTYPE;
    previous integration_inventory_source_acceptance%ROWTYPE;
    lineage_count integer;
BEGIN
    IF NEW.state <> 'ACTIVE' OR NEW.retired_at IS NOT NULL THEN
        RAISE EXCEPTION 'inventory acceptance must start active';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM integration_organization o
        JOIN integration_connection c ON c.organization_id=o.organization_id
        WHERE o.organization_id=NEW.organization_id AND c.connection_id=NEW.connection_id
          AND o.status='ACTIVE' AND c.status IN ('ACTIVE','SUSPENDED')
    ) THEN RAISE EXCEPTION 'inventory acceptance scope unavailable'; END IF;

    SELECT * INTO candidate FROM integration_inventory_canonical_observation
    WHERE organization_id=NEW.organization_id AND observation_id=NEW.observation_id;
    IF NOT FOUND OR candidate.connection_id <> NEW.connection_id
       OR candidate.capability <> NEW.capability
       OR candidate.input_progress_version <> NEW.source_progress_version
       OR candidate.record_ordinal <> NEW.source_record_ordinal
       OR candidate.projection_revision <> NEW.projection_revision
       OR candidate.mapping_decision_id <> NEW.mapping_decision_id
       OR candidate.mapping_revision <> NEW.mapping_revision
       OR candidate.target_item_id <> NEW.target_item_id
       OR candidate.target_location_id IS DISTINCT FROM NEW.target_location_id
       OR candidate.target_unit_id <> NEW.target_unit_id
       OR candidate.factor_numerator <> NEW.factor_numerator
       OR candidate.factor_denominator <> NEW.factor_denominator THEN
        RAISE EXCEPTION 'inventory acceptance candidate unavailable';
    END IF;

    SELECT * INTO root FROM integration_inventory_source_mapping
    WHERE organization_id=NEW.organization_id AND decision_id=NEW.lineage_root_decision_id;
    SELECT * INTO mapping FROM integration_inventory_source_mapping
    WHERE organization_id=NEW.organization_id AND decision_id=NEW.mapping_decision_id;
    IF root.decision_id IS NULL OR root.revision <> 1 OR root.supersedes_decision_id IS NOT NULL
       OR mapping.decision_id IS NULL OR mapping.state <> 'ACTIVE'
       OR root.connection_id <> NEW.connection_id OR root.capability <> NEW.capability
       OR mapping.connection_id <> NEW.connection_id OR mapping.capability <> NEW.capability
       OR root.source_item_ref <> mapping.source_item_ref
       OR root.source_location_ref IS DISTINCT FROM mapping.source_location_ref
       OR root.source_unit_code IS DISTINCT FROM mapping.source_unit_code THEN
        RAISE EXCEPTION 'inventory acceptance lineage unavailable';
    END IF;

    WITH RECURSIVE lineage AS (
        SELECT decision_id, supersedes_decision_id, revision FROM integration_inventory_source_mapping
        WHERE organization_id=NEW.organization_id AND decision_id=NEW.mapping_decision_id
        UNION ALL
        SELECT parent.decision_id, parent.supersedes_decision_id, parent.revision
        FROM integration_inventory_source_mapping parent JOIN lineage child
          ON child.supersedes_decision_id=parent.decision_id
        WHERE parent.organization_id=NEW.organization_id
          AND parent.connection_id=NEW.connection_id AND parent.capability=NEW.capability
          AND parent.source_item_ref=root.source_item_ref
          AND parent.source_location_ref IS NOT DISTINCT FROM root.source_location_ref
          AND parent.source_unit_code IS NOT DISTINCT FROM root.source_unit_code
          AND parent.revision=child.revision-1
    ) SELECT count(*) INTO lineage_count FROM lineage
      WHERE decision_id=NEW.lineage_root_decision_id AND revision=1;
    IF lineage_count <> 1 THEN RAISE EXCEPTION 'inventory acceptance lineage unavailable'; END IF;

    IF NOT EXISTS (SELECT 1 FROM integration_inventory_source_balance e
        WHERE e.organization_id=NEW.organization_id AND e.connection_id=NEW.connection_id
          AND e.capability=NEW.capability
          AND e.input_progress_version=NEW.source_progress_version
          AND e.record_ordinal=NEW.source_record_ordinal
          AND e.source_item_ref=mapping.source_item_ref
          AND e.source_location_ref IS NOT DISTINCT FROM mapping.source_location_ref
          AND e.source_unit_code IS NOT DISTINCT FROM mapping.source_unit_code)
       OR NOT EXISTS (SELECT 1 FROM inventory_item_identity WHERE
          organization_id=NEW.organization_id AND identity_id=NEW.target_item_id AND state='ACTIVE')
       OR NOT EXISTS (SELECT 1 FROM inventory_unit_identity WHERE
          organization_id=NEW.organization_id AND identity_id=NEW.target_unit_id AND state='ACTIVE')
       OR (NEW.target_location_id IS NOT NULL AND NOT EXISTS (
          SELECT 1 FROM inventory_location_identity WHERE organization_id=NEW.organization_id
          AND identity_id=NEW.target_location_id AND state='ACTIVE')) THEN
        RAISE EXCEPTION 'inventory acceptance target unavailable';
    END IF;

    IF NEW.supersedes_acceptance_id IS NOT NULL THEN
        SELECT * INTO previous FROM integration_inventory_source_acceptance
        WHERE organization_id=NEW.organization_id
          AND acceptance_id=NEW.supersedes_acceptance_id;
        IF NOT FOUND OR previous.lineage_root_decision_id <> NEW.lineage_root_decision_id
           OR previous.revision <> NEW.revision-1 OR previous.state <> 'RETIRED' THEN
            RAISE EXCEPTION 'inventory acceptance predecessor unavailable';
        END IF;
        IF NEW.source_progress_version > previous.source_progress_version THEN
            IF NEW.reason NOT IN ('NEW_SOURCE_EVIDENCE', 'OPERATOR_CORRECTION') THEN
                RAISE EXCEPTION 'inventory acceptance succession unavailable';
            END IF;
        ELSIF NEW.source_progress_version = previous.source_progress_version
           AND NEW.source_record_ordinal = previous.source_record_ordinal
           AND NEW.projection_revision > previous.projection_revision
           AND NEW.mapping_revision > previous.mapping_revision THEN
            IF NEW.reason NOT IN ('MAPPING_REINTERPRETATION', 'OPERATOR_CORRECTION') THEN
                RAISE EXCEPTION 'inventory acceptance succession unavailable';
            END IF;
        ELSE
            RAISE EXCEPTION 'inventory acceptance succession unavailable';
        END IF;
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NOT EXISTS (SELECT 1 FROM integration_inventory_source_acceptance a
        WHERE a.organization_id=NEW.organization_id AND a.acceptance_id=NEW.acceptance_id
          AND a.state='RETIRED' AND a.retired_at=NEW.retired_at) THEN
        RAISE EXCEPTION 'inventory acceptance retirement unavailable';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NOT EXISTS (SELECT 1 FROM integration_inventory_source_acceptance_retirement r
        WHERE r.organization_id=NEW.organization_id AND r.acceptance_id=NEW.acceptance_id
          AND r.retired_at=NEW.retired_at) THEN
        RAISE EXCEPTION 'inventory acceptance retirement audit unavailable';
    END IF;
    RETURN NEW;
END;

DECLARE
    root integration_inventory_source_mapping%ROWTYPE;
    anchor integration_inventory_source_acceptance%ROWTYPE;
    observation integration_inventory_canonical_observation%ROWTYPE;
    mapping integration_inventory_source_mapping%ROWTYPE;
    previous integration_inventory_measure_selection%ROWTYPE;
    lineage_count integer;
BEGIN
    IF NEW.state <> 'ACTIVE' OR NEW.retired_at IS NOT NULL THEN
        RAISE EXCEPTION 'inventory measure selection must start active';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM integration_organization o
        JOIN integration_connection c ON c.organization_id=o.organization_id
        WHERE o.organization_id=NEW.organization_id AND c.connection_id=NEW.connection_id
          AND o.status='ACTIVE' AND c.status IN ('ACTIVE','SUSPENDED')
    ) THEN RAISE EXCEPTION 'inventory measure selection scope unavailable'; END IF;

    SELECT * INTO root FROM integration_inventory_source_mapping
    WHERE organization_id=NEW.organization_id AND decision_id=NEW.lineage_root_decision_id;
    SELECT * INTO anchor FROM integration_inventory_source_acceptance
    WHERE organization_id=NEW.organization_id AND acceptance_id=NEW.anchor_acceptance_id;
    SELECT * INTO observation FROM integration_inventory_canonical_observation
    WHERE organization_id=NEW.organization_id AND observation_id=NEW.anchor_observation_id;
    IF root.decision_id IS NULL OR root.revision <> 1 OR root.supersedes_decision_id IS NOT NULL
       OR anchor.acceptance_id IS NULL OR anchor.state <> 'ACTIVE'
       OR anchor.lineage_root_decision_id <> NEW.lineage_root_decision_id
       OR anchor.connection_id <> NEW.connection_id OR anchor.capability <> NEW.capability
       OR anchor.revision <> NEW.anchor_acceptance_revision
       OR anchor.observation_id <> NEW.anchor_observation_id
       OR observation.observation_id IS NULL
       OR observation.connection_id <> NEW.connection_id OR observation.capability <> NEW.capability
       OR observation.observation_id <> anchor.observation_id
       OR observation.mapping_decision_id <> anchor.mapping_decision_id
       OR observation.mapping_revision <> anchor.mapping_revision
       OR observation.target_item_id <> anchor.target_item_id
       OR observation.target_location_id IS DISTINCT FROM anchor.target_location_id
       OR observation.target_unit_id <> anchor.target_unit_id
       OR observation.factor_numerator <> anchor.factor_numerator
       OR observation.factor_denominator <> anchor.factor_denominator
       OR NOT canonical_inventory_measure_present(observation, NEW.measure) THEN
        RAISE EXCEPTION 'inventory measure selection anchor unavailable';
    END IF;

    SELECT * INTO mapping FROM integration_inventory_source_mapping
    WHERE organization_id=NEW.organization_id AND decision_id=anchor.mapping_decision_id;
    IF mapping.decision_id IS NULL OR mapping.state <> 'ACTIVE'
       OR mapping.connection_id <> NEW.connection_id OR mapping.capability <> NEW.capability
       OR root.connection_id <> NEW.connection_id OR root.capability <> NEW.capability
       OR root.source_item_ref <> mapping.source_item_ref
       OR root.source_location_ref IS DISTINCT FROM mapping.source_location_ref
       OR root.source_unit_code IS DISTINCT FROM mapping.source_unit_code THEN
        RAISE EXCEPTION 'inventory measure selection lineage unavailable';
    END IF;

    WITH RECURSIVE lineage AS (
        SELECT decision_id, supersedes_decision_id, revision FROM integration_inventory_source_mapping
        WHERE organization_id=NEW.organization_id AND decision_id=anchor.mapping_decision_id
        UNION ALL
        SELECT p.decision_id,p.supersedes_decision_id,p.revision
        FROM integration_inventory_source_mapping p JOIN lineage c
          ON c.supersedes_decision_id=p.decision_id
        WHERE p.organization_id=NEW.organization_id AND p.connection_id=NEW.connection_id
          AND p.capability=NEW.capability AND p.source_item_ref=root.source_item_ref
          AND p.source_location_ref IS NOT DISTINCT FROM root.source_location_ref
          AND p.source_unit_code IS NOT DISTINCT FROM root.source_unit_code
          AND p.revision=c.revision-1
    ) SELECT count(*) INTO lineage_count FROM lineage
      WHERE decision_id=NEW.lineage_root_decision_id AND revision=1;
    IF lineage_count <> 1 THEN
        RAISE EXCEPTION 'inventory measure selection lineage unavailable';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM inventory_item_identity WHERE
        organization_id=NEW.organization_id AND identity_id=anchor.target_item_id AND state='ACTIVE')
       OR NOT EXISTS (SELECT 1 FROM inventory_unit_identity WHERE
        organization_id=NEW.organization_id AND identity_id=anchor.target_unit_id AND state='ACTIVE')
       OR (anchor.target_location_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM inventory_location_identity WHERE organization_id=NEW.organization_id
          AND identity_id=anchor.target_location_id AND state='ACTIVE')) THEN
        RAISE EXCEPTION 'inventory measure selection target unavailable';
    END IF;

    IF NEW.supersedes_selection_id IS NOT NULL THEN
        SELECT * INTO previous FROM integration_inventory_measure_selection
        WHERE organization_id=NEW.organization_id AND selection_id=NEW.supersedes_selection_id;
        IF NOT FOUND OR previous.lineage_root_decision_id <> NEW.lineage_root_decision_id
           OR previous.revision <> NEW.revision-1 OR previous.state <> 'RETIRED'
           OR previous.measure = NEW.measure
           OR NOT EXISTS (
                SELECT 1 FROM integration_inventory_measure_selection_retirement r
                WHERE r.organization_id=NEW.organization_id
                  AND r.selection_id=previous.selection_id
                  AND r.reason=NEW.reason AND r.retired_at=previous.retired_at
           ) THEN
            RAISE EXCEPTION 'inventory measure selection predecessor unavailable';
        END IF;
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NOT EXISTS (SELECT 1 FROM integration_inventory_measure_selection s
        WHERE s.organization_id=NEW.organization_id AND s.selection_id=NEW.selection_id
          AND s.state='RETIRED' AND s.retired_at=NEW.retired_at) THEN
        RAISE EXCEPTION 'inventory measure selection retirement unavailable';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NOT EXISTS (SELECT 1 FROM integration_inventory_measure_selection_retirement r
        WHERE r.organization_id=NEW.organization_id AND r.selection_id=NEW.selection_id
          AND r.retired_at=NEW.retired_at) THEN
        RAISE EXCEPTION 'inventory measure selection retirement audit unavailable';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF (SELECT count(*) FROM integration_inventory_candidate_snapshot_member m
        WHERE m.organization_id=NEW.organization_id AND m.snapshot_id=NEW.snapshot_id)
       <> NEW.member_count THEN
        RAISE EXCEPTION 'inventory candidate snapshot member count mismatch';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM integration_organization
        WHERE organization_id=NEW.organization_id AND status='ACTIVE'
    ) THEN
        RAISE EXCEPTION 'marketplace financial trace scope unavailable';
    END IF;
    NEW.opened_at := transaction_timestamp();
    RETURN NEW;
END;

BEGIN
    NEW.recorded_at := transaction_timestamp();
    RETURN NEW;
END;

DECLARE
    target_trace_id uuid;
    target_stage text;
    target_basis text;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM integration_organization
        WHERE organization_id=NEW.organization_id AND status='ACTIVE'
    ) THEN
        RAISE EXCEPTION 'marketplace financial ledger scope unavailable';
    END IF;

    IF NEW.corrects_entry_id IS NOT NULL THEN
        SELECT trace_id, stage, basis
          INTO target_trace_id, target_stage, target_basis
          FROM marketplace_financial_ledger_entry
         WHERE organization_id=NEW.organization_id
           AND entry_id=NEW.corrects_entry_id;

        IF target_trace_id IS NULL OR
           target_trace_id <> NEW.trace_id OR
           target_stage <> NEW.stage OR
           target_basis <> NEW.basis THEN
            RAISE EXCEPTION 'marketplace financial correction target unavailable';
        END IF;
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NEW.current_version <> 0 THEN
        RAISE EXCEPTION 'marketplace economic evidence subject must start at version zero';
    END IF;
    RETURN NEW;
END;

BEGIN
    IF NEW.organization_id IS DISTINCT FROM OLD.organization_id OR
       NEW.marketplace_order_id IS DISTINCT FROM OLD.marketplace_order_id OR
       NEW.marketplace_key IS DISTINCT FROM OLD.marketplace_key OR
       NEW.external_order_id IS DISTINCT FROM OLD.external_order_id OR
       NEW.currency IS DISTINCT FROM OLD.currency THEN
        RAISE EXCEPTION 'marketplace economic evidence subject identity is immutable';
    END IF;
    IF NEW.current_version <> OLD.current_version + 1 THEN
        RAISE EXCEPTION 'marketplace economic evidence version must advance by one';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM marketplace_economic_evidence_update
        WHERE organization_id = NEW.organization_id
          AND marketplace_order_id = NEW.marketplace_order_id
          AND evidence_version = NEW.current_version
    ) THEN
        RAISE EXCEPTION 'marketplace economic evidence version requires journal history';
    END IF;
    RETURN NEW;
END;

BEGIN
    NEW.committed_at := transaction_timestamp();
    RETURN NEW;
END;

DECLARE
    expected_identifier_kind text;
    root_version bigint;
BEGIN
    expected_identifier_kind := CASE NEW.change_kind
        WHEN 'FACT' THEN 'FACT'
        WHEN 'ATTEMPT' THEN 'ATTEMPT'
        WHEN 'CORRECTION' THEN 'CORRECTION'
    END;

    IF NOT EXISTS (
        SELECT 1
        FROM marketplace_economic_evidence_identifier
        WHERE organization_id = NEW.organization_id
          AND marketplace_order_id = NEW.marketplace_order_id
          AND observation_id = NEW.update_id
          AND evidence_version = NEW.evidence_version
          AND identifier_kind = expected_identifier_kind
    ) THEN
        RAISE EXCEPTION 'marketplace economic evidence update identifier is inconsistent';
    END IF;

    SELECT current_version INTO root_version
    FROM marketplace_economic_evidence_subject
    WHERE organization_id = NEW.organization_id
      AND marketplace_order_id = NEW.marketplace_order_id;

    IF root_version IS NULL OR root_version < NEW.evidence_version THEN
        RAISE EXCEPTION 'marketplace economic evidence root version is inconsistent';
    END IF;
    RETURN NEW;
END;

DECLARE
    subtype_count integer;
BEGIN
    subtype_count := (
        SELECT count(*)
        FROM marketplace_economic_evidence_component_fact
        WHERE organization_id = NEW.organization_id
          AND marketplace_order_id = NEW.marketplace_order_id
          AND fact_id = NEW.fact_id
    ) + (
        SELECT count(*)
        FROM marketplace_economic_evidence_external_identity_fact
        WHERE organization_id = NEW.organization_id
          AND marketplace_order_id = NEW.marketplace_order_id
          AND fact_id = NEW.fact_id
    ) + (
        SELECT count(*)
        FROM marketplace_economic_evidence_order_occurrence_fact
        WHERE organization_id = NEW.organization_id
          AND marketplace_order_id = NEW.marketplace_order_id
          AND fact_id = NEW.fact_id
    );

    IF subtype_count <> 1 THEN
        RAISE EXCEPTION 'marketplace economic evidence fact subtype is inconsistent';
    END IF;
    RETURN NEW;
END;

BEGIN
    RAISE EXCEPTION 'marketplace economic evidence history is append-only';
END;

BEGIN
    RAISE EXCEPTION 'marketplace economic evidence subject cannot be deleted';
END;

BEGIN
    NEW.updated_at := transaction_timestamp();
    RETURN NEW;
END;

BEGIN
    IF NEW.marketplace_key <> 'mercado-livre' THEN
        RAISE EXCEPTION 'marketplace order identity source mismatch';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM integration_mercado_livre_order_source_observation source
        WHERE source.organization_id = NEW.organization_id
          AND source.connection_id = NEW.first_source_connection_id
          AND source.capability = NEW.first_source_capability
          AND source.input_progress_version = NEW.first_source_input_progress_version
          AND source.record_ordinal = NEW.first_source_record_ordinal
          AND source.external_order_ref = NEW.external_order_id
          AND source.currency = NEW.currency
    ) THEN
        RAISE EXCEPTION 'marketplace order identity source mismatch';
    END IF;

    RETURN NEW;
END;

DECLARE
    source_currency char(3);
    source_external_order_id text;
    identity_currency char(3);
    identity_external_order_id text;
    identity_marketplace_key text;
BEGIN
    SELECT source.currency, source.external_order_ref
      INTO source_currency, source_external_order_id
      FROM integration_mercado_livre_order_source_observation source
     WHERE source.organization_id = NEW.organization_id
       AND source.connection_id = NEW.source_connection_id
       AND source.capability = NEW.source_capability
       AND source.input_progress_version = NEW.source_input_progress_version
       AND source.record_ordinal = NEW.source_record_ordinal;

    SELECT identity.currency, identity.external_order_id, identity.marketplace_key
      INTO identity_currency, identity_external_order_id, identity_marketplace_key
      FROM marketplace_order_identity_registry identity
     WHERE identity.organization_id = NEW.organization_id
       AND identity.marketplace_order_id = NEW.marketplace_order_id;

    IF source_external_order_id IS NULL OR identity_external_order_id IS NULL OR
       identity_marketplace_key <> 'mercado-livre' OR
       source_external_order_id <> identity_external_order_id THEN
        RAISE EXCEPTION 'marketplace order promotion identity mismatch';
    END IF;

    IF NEW.outcome = 'IDENTITY_CONFLICT' THEN
        IF source_currency = identity_currency THEN
            RAISE EXCEPTION 'marketplace order identity conflict is not proven';
        END IF;
    ELSIF source_currency <> identity_currency THEN
        RAISE EXCEPTION 'marketplace order promotion currency mismatch';
    END IF;

    RETURN NEW;
END;

BEGIN
    RAISE EXCEPTION 'marketplace order promotion state is append-only';
END;

DECLARE
    source_currency char(3);
    source_external_order_id text;
    source_date_closed timestamptz;
    source_total_amount numeric(24,6);
    source_observed_at timestamptz;

    identity_currency char(3);
    identity_external_order_id text;
    identity_marketplace_key text;

    evidence_family text;
    evidence_observed_at timestamptz;
    evidence_component_type text;
    evidence_direction text;
    evidence_magnitude numeric(24,6);
    evidence_currency char(3);
    evidence_source_kind text;
    evidence_source_system_key text;
    evidence_source_external_reference text;
    evidence_occurred_at timestamptz;
    evidence_quality text;
    evidence_coverage text;
BEGIN
    SELECT
        source.currency,
        source.external_order_ref,
        source.date_closed,
        source.total_amount,
        source.observed_at
      INTO
        source_currency,
        source_external_order_id,
        source_date_closed,
        source_total_amount,
        source_observed_at
      FROM integration_mercado_livre_order_source_observation source
     WHERE source.organization_id = NEW.organization_id
       AND source.connection_id = NEW.source_connection_id
       AND source.capability = NEW.source_capability
       AND source.input_progress_version = NEW.source_input_progress_version
       AND source.record_ordinal = NEW.source_record_ordinal;

    SELECT
        identity.currency,
        identity.external_order_id,
        identity.marketplace_key
      INTO
        identity_currency,
        identity_external_order_id,
        identity_marketplace_key
      FROM marketplace_order_identity_registry identity
     WHERE identity.organization_id = NEW.organization_id
       AND identity.marketplace_order_id = NEW.marketplace_order_id;

    IF source_external_order_id IS NULL OR
       identity_external_order_id IS NULL OR
       identity_marketplace_key IS DISTINCT FROM 'mercado-livre' OR
       source_external_order_id IS DISTINCT FROM identity_external_order_id THEN
        RAISE EXCEPTION
            'marketplace order revenue promotion identity mismatch';
    END IF;

    IF source_date_closed IS NULL THEN
        RAISE EXCEPTION
            'marketplace order revenue source is not closed';
    END IF;

    IF NEW.outcome = 'IDENTITY_CONFLICT' THEN
        IF source_currency IS NOT DISTINCT FROM identity_currency THEN
            RAISE EXCEPTION
                'marketplace order revenue identity conflict is not proven';
        END IF;
    ELSIF source_currency IS DISTINCT FROM identity_currency THEN
        RAISE EXCEPTION
            'marketplace order revenue promotion currency mismatch';
    END IF;

    IF NEW.outcome IN ('PROMOTED', 'DUPLICATE') THEN
        IF NEW.economic_observation_id IS NULL THEN
            RAISE EXCEPTION
                'successful revenue promotion requires explicit economic observation lineage';
        END IF;

        SELECT
            fact.family,
            fact.observed_at,
            component.component_type,
            component.direction,
            component.magnitude,
            component.currency,
            component.source_kind,
            component.source_system_key,
            component.source_external_reference,
            component.occurred_at,
            component.quality,
            component.coverage
          INTO
            evidence_family,
            evidence_observed_at,
            evidence_component_type,
            evidence_direction,
            evidence_magnitude,
            evidence_currency,
            evidence_source_kind,
            evidence_source_system_key,
            evidence_source_external_reference,
            evidence_occurred_at,
            evidence_quality,
            evidence_coverage
          FROM marketplace_economic_evidence_fact fact
          JOIN marketplace_economic_evidence_component_fact component
            ON component.organization_id = fact.organization_id
           AND component.marketplace_order_id = fact.marketplace_order_id
           AND component.fact_id = fact.fact_id
         WHERE fact.organization_id = NEW.organization_id
           AND fact.marketplace_order_id = NEW.marketplace_order_id
           AND fact.fact_id = NEW.economic_observation_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION
                'revenue promotion economic observation is unavailable';
        END IF;

        IF evidence_family IS DISTINCT FROM 'MARKETPLACE_ORDER' OR
           evidence_component_type IS DISTINCT FROM 'REVENUE' OR
           evidence_direction IS DISTINCT FROM 'ADDITION' OR
           evidence_quality IS DISTINCT FROM 'CONFIRMED' OR
           evidence_coverage IS DISTINCT FROM 'PARTIAL' OR
           evidence_source_kind IS DISTINCT FROM 'MARKETPLACE' OR
           evidence_source_system_key IS DISTINCT FROM 'br.com.mercadolivre' OR
           evidence_source_external_reference IS DISTINCT FROM source_external_order_id OR
           evidence_currency IS DISTINCT FROM source_currency OR
           evidence_magnitude IS DISTINCT FROM source_total_amount OR
           evidence_occurred_at IS DISTINCT FROM source_date_closed OR
           evidence_observed_at IS DISTINCT FROM source_observed_at THEN
            RAISE EXCEPTION
                'revenue promotion economic observation mismatch';
        END IF;
    ELSE
        IF NEW.economic_observation_id IS NOT NULL THEN
            RAISE EXCEPTION
                'conflict revenue promotion must not claim economic observation lineage';
        END IF;
    END IF;

    RETURN NEW;
END;

