DECLARE
    stage_name text;
    amount_text text;
    amount_value numeric;
    key_count integer;
    required_stages text[] :=
        ARRAY[
            'SALE',
            'MARKETPLACE_COMMISSION',
            'MARKETPLACE_FEE',
            'SHIPPING',
            'ADVERTISING',
            'TAX',
            'PRODUCT_COST',
            'FINANCIAL_COST',
            'OTHER_ADJUSTMENT',
            'SETTLEMENT',
            'PAYMENT_ACCOUNT',
            'BANK'
        ];
BEGIN
    IF value IS NULL OR jsonb_typeof(value) <> 'object' THEN
        RETURN FALSE;
    END IF;

    SELECT count(*)
      INTO key_count
      FROM jsonb_object_keys(value);

    IF key_count <> array_length(required_stages, 1) THEN
        RETURN FALSE;
    END IF;

    FOREACH stage_name IN ARRAY required_stages
    LOOP
        IF NOT value ? stage_name THEN
            RETURN FALSE;
        END IF;

        IF jsonb_typeof(value -> stage_name) <> 'string' THEN
            RETURN FALSE;
        END IF;

        amount_text := value ->> stage_name;

        IF amount_text !~
            '^(0|[1-9][0-9]*)(\.[0-9]{1,6})?$'
        THEN
            RETURN FALSE;
        END IF;

        amount_value := amount_text::numeric;

        IF amount_value >= 1000000000000000000 THEN
            RETURN FALSE;
        END IF;
    END LOOP;

    RETURN TRUE;
END;

