    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'transaction-identity/id/1:' || org || ':' || id,
            0
        )
    );

    IF NOT public.transaction_identity_progress_lock(org,conn) THEN
