                conn || ':' ||
                pg_catalog.octet_length(ref) || ':' ||
                ref,
            'transaction-identity/target/1:' ||
                org || ':' ||
                target
        ])
        ORDER BY 1
    LOOP
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(resource,0)
        );
    END LOOP;
END;

