 IF NOT FOUND THEN RAISE EXCEPTION 'Principal unavailable' USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE'; END IF;
 IF principal.mercado_livre_connection_id IS DISTINCT FROM p_mercado_livre_connection_id
