 IF NOT FOUND THEN RAISE EXCEPTION 'Evidence unavailable' USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE'; END IF;
 FOR resource IN SELECT unnest(ARRAY[
