       AND g.principal_id=p_principal_id
       AND g.permission=p_permission
     ORDER BY g.revision DESC
     LIMIT 1;

    IF NOT FOUND
       OR current_grant.state IS DISTINCT FROM 'ENABLED'
       OR current_grant.grant_id IS DISTINCT FROM p_grant_id
       OR current_grant.revision IS DISTINCT FROM p_grant_revision THEN
        RAISE EXCEPTION 'Command authority unavailable'
            USING ERRCODE='P0012';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'transaction-identity/id/1:' || p_organization_id || ':' || p_decision_id,
            0
        )
    );

    proposed.organization_id := p_organization_id;
    proposed.decision_id := p_decision_id;
    proposed.omie_connection_id := p_decision_omie_connection_id;
    proposed.source_order_reference := p_decision_source_order_reference;
    proposed.marketplace_order_id := p_decision_marketplace_order_id;
    proposed.kind := 'CONFIRMED';
    proposed.reason := 'EXPLICIT_CONFIRMATION';
    proposed.revision := 1;
    proposed.supersedes_decision_id := NULL;
    proposed.ml_connection_id := p_mercado_livre_connection_id;
    proposed.principal_id := p_principal_id;
    proposed.provenance := p_provenance;
    proposed_intent := public.transaction_identity_intent(proposed);

    SELECT d.*
      INTO existing
      FROM public.marketplace_transaction_identity_decision d
     WHERE d.organization_id=p_organization_id
       AND d.decision_id=p_decision_id;

    IF FOUND THEN
        stored_intent := public.transaction_identity_intent(existing);
        stored_semantic := public.transaction_identity_fingerprint(existing);

        IF existing.intent_fingerprint IS DISTINCT FROM stored_intent
           OR existing.decision_semantic_fingerprint IS DISTINCT FROM stored_semantic THEN
            RAISE EXCEPTION 'Historical decision integrity failure'
                USING ERRCODE='23514';
        END IF;

        IF existing.intent_fingerprint IS DISTINCT FROM proposed_intent THEN
            RAISE EXCEPTION 'Decision replay integrity failure'
                USING ERRCODE='23514';
        END IF;

        outcome := 'ALREADY_APPLIED';
        result_decision_id := existing.decision_id;
        result_decision_semantic_fingerprint := existing.decision_semantic_fingerprint::text;
        result_decided_at := existing.decided_at;
        RETURN NEXT;
        RETURN;
    END IF;

    SELECT count(*)
      INTO linked_grant_count
      FROM public.command_authority_operation o
     WHERE o.organization_id=p_organization_id
       AND o.operation='GRANT'
       AND o.principal_id=p_principal_id
       AND o.grant_id=p_grant_id
       AND o.grant_revision=p_grant_revision
       AND o.permission='TRANSACTION_IDENTITY_DECISION_WRITE'
       AND o.state='ENABLED'
       AND o.attestation_manifest_id IS NOT NULL;

    IF linked_grant_count=0 THEN
        RAISE EXCEPTION 'Attested route unavailable'
            USING ERRCODE='P0018',DETAIL='ROUTE_MISMATCH';
    ELSIF linked_grant_count>1 THEN
        RAISE EXCEPTION 'Ambiguous linked grant route'
            USING ERRCODE='P0018',DETAIL='INTEGRITY_FAILURE';
    END IF;

    SELECT o.*
      INTO STRICT linked_operation
      FROM public.command_authority_operation o
     WHERE o.organization_id=p_organization_id
       AND o.operation='GRANT'
       AND o.principal_id=p_principal_id
       AND o.grant_id=p_grant_id
       AND o.grant_revision=p_grant_revision
       AND o.permission='TRANSACTION_IDENTITY_DECISION_WRITE'
       AND o.state='ENABLED'
       AND o.attestation_manifest_id IS NOT NULL;

    IF linked_operation.attestation_manifest_id IS DISTINCT FROM p_claim_manifest_id
       OR p_claim_organization_id IS DISTINCT FROM p_organization_id THEN
        RAISE EXCEPTION 'Linked grant manifest scope mismatch'
            USING ERRCODE='P0017',DETAIL='SCOPE_MISMATCH';
    END IF;

    SELECT a.*
      INTO accepted
      FROM public.s2a_accepted_attestation a
     WHERE a.organization_id=p_organization_id
       AND a.manifest_id=linked_operation.attestation_manifest_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Accepted artifact unavailable'
            USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE';
    END IF;

    reconstructed := public.s2a_v041_manifest_bytes(
        p_schema_version,
        p_claim_manifest_id,
        p_claim_organization_id,
        p_mercado_livre_connection_id,
        p_omie_connection_id,
        p_source_order_reference,
        p_integration_reference,
        p_marketplace_order_id,
        p_permission,
        p_accountable_operator,
        p_approval_source,
        p_approval_window_start,
        p_approval_window_end,
        p_revocation_owner,
        p_credential_custodian,
        p_credential_delivery_method,
        p_credential_rotation_owner,
        p_immediate_revocation_policy,
        p_reason,
        p_provenance,
        p_correlation_id,
        p_evidence_binding_fingerprint
    );
    reconstructed_digest := pg_catalog.encode(pg_catalog.sha256(reconstructed),'hex');

    IF reconstructed IS DISTINCT FROM accepted.canonical_manifest_bytes
       OR reconstructed_digest IS DISTINCT FROM accepted.manifest_digest THEN
        RAISE EXCEPTION 'Accepted artifact integrity failure'
            USING ERRCODE='P0018',DETAIL='INTEGRITY_FAILURE';
    END IF;

    IF p_decision_omie_connection_id IS DISTINCT FROM p_omie_connection_id
       OR p_decision_source_order_reference IS DISTINCT FROM p_source_order_reference
       OR p_decision_marketplace_order_id IS DISTINCT FROM p_marketplace_order_id
       OR p_permission IS DISTINCT FROM 'TRANSACTION_IDENTITY_DECISION_WRITE'
       OR current_principal.mercado_livre_connection_id IS DISTINCT FROM p_mercado_livre_connection_id
       OR current_principal.omie_connection_id IS DISTINCT FROM p_omie_connection_id THEN
        RAISE EXCEPTION 'Decision claim scope mismatch'
            USING ERRCODE='P0017',DETAIL='SCOPE_MISMATCH';
    END IF;

    PERFORM 1
      FROM public.integration_connector_progress cp
     WHERE cp.organization_id=p_organization_id
       AND cp.connection_id=p_omie_connection_id
       AND cp.capability='marketplace-economic.omie-transaction-evidence.reacquisition-v3'
     FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Evidence unavailable'
            USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE';
    END IF;

    FOR lock_resource IN
        SELECT pg_catalog.unnest(ARRAY[
            'transaction-identity/subject/1:' || p_organization_id || ':' || p_omie_connection_id || ':' ||
                pg_catalog.octet_length(p_source_order_reference) || ':' || p_source_order_reference,
            'transaction-identity/target/1:' || p_organization_id || ':' || p_marketplace_order_id
        ])
        ORDER BY 1
    LOOP
        PERFORM pg_catalog.pg_advisory_xact_lock(
            pg_catalog.hashtextextended(lock_resource,0)
        );
    END LOOP;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            's2a-attestation/manifest/1:' || p_organization_id || ':' || linked_operation.attestation_manifest_id,
            0
        )
    );

    SELECT a.*
      INTO accepted
      FROM public.s2a_accepted_attestation a
     WHERE a.organization_id=p_organization_id
       AND a.manifest_id=linked_operation.attestation_manifest_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Accepted artifact unavailable'
            USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE';
    END IF;

    SELECT *
      INTO snapshot
      FROM public.s2a_v042_revalidate_snapshot(
        p_organization_id,
        linked_operation.attestation_manifest_id,
        p_schema_version,
        p_claim_manifest_id,
        p_claim_organization_id,
        p_mercado_livre_connection_id,
        p_omie_connection_id,
        p_source_order_reference,
        p_integration_reference,
        p_marketplace_order_id,
        p_permission,
        p_accountable_operator,
        p_approval_source,
        p_approval_window_start,
        p_approval_window_end,
        p_revocation_owner,
        p_credential_custodian,
        p_credential_delivery_method,
        p_credential_rotation_owner,
        p_immediate_revocation_policy,
        p_reason,
        p_provenance,
        p_correlation_id,
        p_evidence_binding_fingerprint,
        accepted.artifact_version,
        accepted.canonicalization_version,
        accepted.canonical_manifest_bytes,
        accepted.manifest_digest,
        accepted.canonical_signature_preimage_bytes,
        accepted.algorithm_id,
        (SELECT k.signer_subject_id
           FROM public.s2a_signer_key_revision k
          WHERE k.organization_id=accepted.organization_id
            AND k.signer_key_id=accepted.signer_key_id
            AND k.revision=accepted.signer_key_revision),
        accepted.signer_key_id,
        accepted.signer_key_revision,
        accepted.signer_key_fingerprint,
        accepted.signer_key_lineage_fingerprint,
        accepted.subject_public_key_info_der,
        accepted.signature_bytes,
        accepted.signer_authority_id,
        accepted.signer_authority_revision,
        accepted.signer_authority_fingerprint,
        accepted.verified_at,
        accepted.accepted_proof_fingerprint,
        p_evidence_binding_fingerprint
    );

    result_observed_effect_time := pg_catalog.clock_timestamp()::timestamptz(6);

    SELECT o.status
      INTO observed_organization_status
      FROM public.integration_organization o
     WHERE o.organization_id=p_organization_id
     FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Governance unavailable'
            USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE';
    END IF;

    result_observed_organization_status := observed_organization_status;

    IF observed_organization_status IS DISTINCT FROM 'ACTIVE'
       OR result_observed_effect_time<p_approval_window_start
       OR result_observed_effect_time>=p_approval_window_end THEN
        RAISE EXCEPTION 'Current approval eligibility denied'
            USING ERRCODE='P0017',DETAIL='EXPIRED_OR_NOT_YET_VALID';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            's2a-governance/signer-key/1:' || p_organization_id || ':' || snapshot.result_signer_key_id,
            0
        )
    );

    SELECT count(*)
      INTO key_leaf_count
      FROM public.s2a_signer_key_revision k
     WHERE k.organization_id=p_organization_id
       AND k.signer_key_id=snapshot.result_signer_key_id
       AND NOT EXISTS (
            SELECT 1
              FROM public.s2a_signer_key_revision successor
             WHERE successor.organization_id=k.organization_id
               AND successor.signer_key_id=k.signer_key_id
               AND successor.supersedes_revision=k.revision
       );

    IF key_leaf_count<>1 THEN
        RAISE EXCEPTION 'Signer key lineage conflict'
            USING ERRCODE='P0016',DETAIL='GOVERNANCE_CONFLICT';
    END IF;

    SELECT k.*
      INTO effective_key
      FROM public.s2a_signer_key_revision k
     WHERE k.organization_id=p_organization_id
       AND k.signer_key_id=snapshot.result_signer_key_id
       AND k.effective_at<=result_observed_effect_time
     ORDER BY k.effective_at DESC,k.revision DESC
     LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Signer key unavailable'
            USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE';
    END IF;

    IF effective_key.valid_from>result_observed_effect_time
       OR effective_key.state IS DISTINCT FROM 'ACTIVE' THEN
        RAISE EXCEPTION 'Signer key ineligible'
            USING ERRCODE='P0017',DETAIL='EXPIRED_OR_NOT_YET_VALID';
    END IF;

    IF effective_key.signer_subject_id IS DISTINCT FROM snapshot.result_signer_subject_id
       OR effective_key.algorithm_id IS DISTINCT FROM snapshot.result_algorithm_id
       OR effective_key.subject_public_key_info_der IS DISTINCT FROM snapshot.result_subject_public_key_info_der
       OR effective_key.signer_key_fingerprint IS DISTINCT FROM snapshot.result_signer_key_fingerprint THEN
        RAISE EXCEPTION 'Signer key scope mismatch'
            USING ERRCODE='P0017',DETAIL='SCOPE_MISMATCH';
    END IF;

    result_observed_effective_signer_key_revision := effective_key.revision;
    result_observed_effective_signer_key_state := effective_key.state;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            's2a-governance/signer-authority-scope/1:' || p_organization_id || ':' ||
            snapshot.result_signer_subject_id || ':' || snapshot.result_signer_key_id ||
            ':S2A_FIELD_PROOF_APPROVAL:TRANSACTION_IDENTITY_DECISION_WRITE',
            0
        )
    );

    SELECT count(*)
      INTO authority_leaf_count
      FROM public.s2a_signer_authority_revision a
     WHERE a.organization_id=p_organization_id
       AND a.signer_subject_id=snapshot.result_signer_subject_id
       AND a.signer_key_id=snapshot.result_signer_key_id
       AND a.approval_action='S2A_FIELD_PROOF_APPROVAL'
       AND a.permission='TRANSACTION_IDENTITY_DECISION_WRITE'
       AND NOT EXISTS (
            SELECT 1
              FROM public.s2a_signer_authority_revision successor
             WHERE successor.organization_id=a.organization_id
               AND successor.supersedes_signer_authority_id=a.signer_authority_id
       );

    IF authority_leaf_count=0 THEN
        RAISE EXCEPTION 'Signer authority unavailable'
            USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE';
    ELSIF authority_leaf_count<>1 THEN
        RAISE EXCEPTION 'Signer authority conflict'
            USING ERRCODE='P0016',DETAIL='GOVERNANCE_CONFLICT';
    END IF;

    SELECT a.*
      INTO STRICT current_authority
      FROM public.s2a_signer_authority_revision a
     WHERE a.organization_id=p_organization_id
       AND a.signer_subject_id=snapshot.result_signer_subject_id
       AND a.signer_key_id=snapshot.result_signer_key_id
       AND a.approval_action='S2A_FIELD_PROOF_APPROVAL'
       AND a.permission='TRANSACTION_IDENTITY_DECISION_WRITE'
       AND NOT EXISTS (
            SELECT 1
              FROM public.s2a_signer_authority_revision successor
             WHERE successor.organization_id=a.organization_id
               AND successor.supersedes_signer_authority_id=a.signer_authority_id
       );

    IF current_authority.signer_key_revision IS DISTINCT FROM effective_key.revision
       OR current_authority.signer_key_fingerprint IS DISTINCT FROM effective_key.signer_key_fingerprint THEN
        RAISE EXCEPTION 'Signer authority key scope mismatch'
            USING ERRCODE='P0017',DETAIL='SCOPE_MISMATCH';
    END IF;

    IF current_authority.state IS DISTINCT FROM 'ENABLED'
       OR current_authority.valid_from>result_observed_effect_time
       OR result_observed_effect_time>=current_authority.valid_until THEN
        RAISE EXCEPTION 'Signer authority ineligible'
            USING ERRCODE='P0017',DETAIL='EXPIRED_OR_NOT_YET_VALID';
    END IF;

    current_evidence := public.s2a_v041_evidence_fingerprint(
        p_organization_id,
        p_marketplace_order_id,
        p_mercado_livre_connection_id,
        p_omie_connection_id,
        p_source_order_reference,
        p_integration_reference
    );

    IF current_evidence IS DISTINCT FROM snapshot.result_signed_evidence_binding_fingerprint THEN
        RAISE EXCEPTION 'Evidence scope mismatch'
            USING ERRCODE='P0017',DETAIL='SCOPE_MISMATCH';
    END IF;

    outcome := 'READY';
    result_decision_id := p_decision_id;
    result_decision_semantic_fingerprint := NULL;
    result_decided_at := NULL;
    result_manifest_id := linked_operation.attestation_manifest_id;
    result_artifact_version := snapshot.result_artifact_version;
    result_schema_version := snapshot.result_schema_version;
    result_canonicalization_version := snapshot.result_canonicalization_version;
    result_canonical_manifest_bytes := snapshot.result_canonical_manifest_bytes;
    result_manifest_digest := snapshot.result_manifest_digest;
    result_signature_preimage_bytes := snapshot.result_signature_preimage_bytes;
    result_algorithm_id := snapshot.result_algorithm_id;
    result_signer_subject_id := snapshot.result_signer_subject_id;
    result_signer_key_id := snapshot.result_signer_key_id;
    result_signer_key_revision := snapshot.result_signer_key_revision;
    result_signer_key_fingerprint := snapshot.result_signer_key_fingerprint;
    result_signer_key_lineage_fingerprint := snapshot.result_signer_key_lineage_fingerprint;
    result_subject_public_key_info_der := snapshot.result_subject_public_key_info_der;
    result_signature_bytes := snapshot.result_signature_bytes;
    result_signer_authority_id := snapshot.result_signer_authority_id;
    result_signer_authority_revision := snapshot.result_signer_authority_revision;
    result_signer_authority_fingerprint := snapshot.result_signer_authority_fingerprint;
    result_verified_at := snapshot.result_verified_at;
    result_accepted_proof_fingerprint := snapshot.result_accepted_proof_fingerprint;
    result_signed_evidence_binding_fingerprint := snapshot.result_signed_evidence_binding_fingerprint;
    result_current_durable_evidence_binding := current_evidence;
    result_observed_current_signer_authority_id := current_authority.signer_authority_id;
    result_observed_current_signer_authority_revision := current_authority.revision;
    result_observed_current_signer_authority_fingerprint := current_authority.signer_authority_fingerprint;
    RETURN NEXT;
END;

DECLARE
    current_principal public.command_principal%ROWTYPE;
    current_credential public.command_credential_revision%ROWTYPE;
    current_grant public.command_permission_grant%ROWTYPE;
    proposed public.marketplace_transaction_identity_decision%ROWTYPE;
    existing public.marketplace_transaction_identity_decision%ROWTYPE;
    persisted public.marketplace_transaction_identity_decision%ROWTYPE;
    linked_operation public.command_authority_operation%ROWTYPE;
    accepted public.s2a_accepted_attestation%ROWTYPE;
    effective_key public.s2a_signer_key_revision%ROWTYPE;
    current_authority public.s2a_signer_authority_revision%ROWTYPE;
    snapshot record;
    proposed_intent text;
    stored_intent text;
    stored_semantic text;
    current_authorization_fingerprint text;
    reconstructed bytea;
    reconstructed_digest text;
    current_evidence text;
    observed_organization_status text;
    observed_effect_time timestamptz(6);
    linked_grant_count bigint;
    key_leaf_count bigint;
    authority_leaf_count bigint;
    prior_action_count bigint;
BEGIN
    IF NOT public.command_authorization_organization_lock(p_organization_id) THEN
        RAISE EXCEPTION 'Command authority unavailable'
            USING ERRCODE='P0012';
    END IF;

    SELECT p.*
      INTO current_principal
      FROM public.command_principal p
     WHERE p.organization_id=p_organization_id
       AND p.principal_id=p_principal_id
     FOR UPDATE;

    IF NOT FOUND
       OR current_principal.mercado_livre_connection_id IS DISTINCT FROM p_ml_connection_id
       OR current_principal.omie_connection_id IS DISTINCT FROM p_decision_omie_connection_id THEN
        RAISE EXCEPTION 'Command authority unavailable'
            USING ERRCODE='P0012';
    END IF;

    SELECT c.*
      INTO current_credential
      FROM public.command_credential_revision c
     WHERE c.organization_id=p_organization_id
       AND c.principal_id=p_principal_id
       AND c.credential_id=p_credential_id
     ORDER BY c.revision DESC
     LIMIT 1;

    IF NOT FOUND
       OR current_credential.revision IS DISTINCT FROM p_credential_revision
       OR current_credential.state IS DISTINCT FROM 'ENABLED' THEN
        RAISE EXCEPTION 'Command authority unavailable'
            USING ERRCODE='P0012';
    END IF;

    IF p_decision_permission IS DISTINCT FROM 'TRANSACTION_IDENTITY_DECISION_WRITE' THEN
        RAISE EXCEPTION 'Command authority unavailable'
            USING ERRCODE='P0012';
    END IF;

    SELECT g.*
      INTO current_grant
      FROM public.command_permission_grant g
     WHERE g.organization_id=p_organization_id
       AND g.principal_id=p_principal_id
       AND g.permission=p_decision_permission
     ORDER BY g.revision DESC
     LIMIT 1;

    IF NOT FOUND
       OR current_grant.state IS DISTINCT FROM 'ENABLED'
       OR current_grant.grant_id IS DISTINCT FROM p_grant_id
       OR current_grant.revision IS DISTINCT FROM p_grant_revision THEN
        RAISE EXCEPTION 'Command authority unavailable'
            USING ERRCODE='P0012';
    END IF;

    current_authorization_fingerprint :=
        public.transaction_identity_grant_fingerprint(
            p_organization_id,
            p_grant_id
        );

    IF p_authorization_semantic_version IS DISTINCT FROM 'command-authorization/1'
       OR p_authorization_fingerprint IS DISTINCT FROM current_authorization_fingerprint THEN
        RAISE EXCEPTION 'Authorization lineage mismatch'
            USING ERRCODE='23514';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'transaction-identity/id/1:' || p_organization_id || ':' || p_decision_id,
            0
        )
    );

    proposed.organization_id := p_organization_id;
    proposed.decision_id := p_decision_id;
    proposed.omie_connection_id := p_decision_omie_connection_id;
    proposed.source_order_reference := p_decision_source_order_reference;
    proposed.marketplace_order_id := p_decision_marketplace_order_id;
    proposed.kind := p_kind;
    proposed.reason := p_decision_reason;
    proposed.revision := p_revision;
    proposed.supersedes_decision_id := p_supersedes_decision_id;
    proposed.ml_connection_id := p_ml_connection_id;
    proposed.ml_capability := p_ml_capability;
    proposed.ml_progress_version := p_ml_progress_version;
    proposed.ml_record_ordinal := p_ml_record_ordinal;
    proposed.external_order_id := p_external_order_id;
    proposed.currency := p_currency;
    proposed.omie_capability := p_omie_capability;
    proposed.omie_progress_version := p_omie_progress_version;
    proposed.omie_record_ordinal := p_omie_record_ordinal;
    proposed.omie_semantic_fingerprint := p_omie_semantic_fingerprint;
    proposed.provider_revision_local := p_provider_revision_local;
    proposed.principal_id := p_principal_id;
    proposed.credential_id := p_credential_id;
    proposed.credential_revision := p_credential_revision;
    proposed.grant_id := p_grant_id;
    proposed.grant_revision := p_grant_revision;
    proposed.permission := p_decision_permission;
    proposed.authorization_semantic_version := p_authorization_semantic_version;
    proposed.authorization_fingerprint := p_authorization_fingerprint;
    proposed.intent_fingerprint := p_intent_fingerprint;
    proposed.decision_semantic_fingerprint := p_decision_semantic_fingerprint;
    proposed.provenance := p_decision_provenance;
    proposed.correlation_id := p_decision_correlation_id;

    proposed_intent := public.transaction_identity_intent(proposed);

    SELECT d.*
      INTO existing
      FROM public.marketplace_transaction_identity_decision d
     WHERE d.organization_id=p_organization_id
       AND d.decision_id=p_decision_id;

    IF FOUND THEN
        stored_intent := public.transaction_identity_intent(existing);
        stored_semantic := public.transaction_identity_fingerprint(existing);

        IF existing.intent_fingerprint IS DISTINCT FROM stored_intent
           OR existing.decision_semantic_fingerprint IS DISTINCT FROM stored_semantic THEN
            RAISE EXCEPTION 'Historical decision integrity failure'
                USING ERRCODE='23514';
        END IF;

        IF p_intent_fingerprint IS DISTINCT FROM proposed_intent
           OR existing.intent_fingerprint IS DISTINCT FROM proposed_intent THEN
            RAISE EXCEPTION 'Decision replay integrity failure'
                USING ERRCODE='23514';
        END IF;

        RETURN QUERY
        SELECT
            'ALREADY_APPLIED'::text,
            existing.decision_id,
            existing.decision_semantic_fingerprint::text,
            existing.decided_at;
        RETURN;
    END IF;

    SELECT count(*)
      INTO linked_grant_count
      FROM public.command_authority_operation o
     WHERE o.organization_id=p_organization_id
       AND o.operation='GRANT'
       AND o.principal_id=p_principal_id
       AND o.grant_id=p_grant_id
       AND o.grant_revision=p_grant_revision
       AND o.permission='TRANSACTION_IDENTITY_DECISION_WRITE'
       AND o.state='ENABLED'
       AND o.attestation_manifest_id IS NOT NULL;

    IF linked_grant_count=0 THEN
        RAISE EXCEPTION 'Attested route unavailable'
            USING ERRCODE='P0018',DETAIL='ROUTE_MISMATCH';
    ELSIF linked_grant_count>1 THEN
        RAISE EXCEPTION 'Ambiguous linked grant route'
            USING ERRCODE='P0018',DETAIL='INTEGRITY_FAILURE';
    END IF;

    SELECT o.*
      INTO STRICT linked_operation
      FROM public.command_authority_operation o
     WHERE o.organization_id=p_organization_id
       AND o.operation='GRANT'
       AND o.principal_id=p_principal_id
       AND o.grant_id=p_grant_id
       AND o.grant_revision=p_grant_revision
       AND o.permission='TRANSACTION_IDENTITY_DECISION_WRITE'
       AND o.state='ENABLED'
       AND o.attestation_manifest_id IS NOT NULL;

    IF linked_operation.attestation_manifest_id IS DISTINCT FROM p_claim_manifest_id
       OR p_claim_organization_id IS DISTINCT FROM p_organization_id THEN
        RAISE EXCEPTION 'Linked grant manifest scope mismatch'
            USING ERRCODE='P0017',DETAIL='SCOPE_MISMATCH';
    END IF;

    SELECT a.*
      INTO accepted
      FROM public.s2a_accepted_attestation a
     WHERE a.organization_id=p_organization_id
       AND a.manifest_id=linked_operation.attestation_manifest_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Accepted artifact unavailable'
            USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE';
    END IF;

    reconstructed := public.s2a_v041_manifest_bytes(
        p_schema_version,
        p_claim_manifest_id,
        p_claim_organization_id,
        p_mercado_livre_connection_id,
        p_omie_connection_id,
        p_source_order_reference,
        p_integration_reference,
        p_marketplace_order_id,
        p_permission,
        p_accountable_operator,
        p_approval_source,
        p_approval_window_start,
        p_approval_window_end,
        p_revocation_owner,
        p_credential_custodian,
        p_credential_delivery_method,
        p_credential_rotation_owner,
        p_immediate_revocation_policy,
        p_reason,
        p_provenance,
        p_correlation_id,
        p_evidence_binding_fingerprint
    );
    reconstructed_digest := pg_catalog.encode(pg_catalog.sha256(reconstructed),'hex');

    IF reconstructed IS DISTINCT FROM accepted.canonical_manifest_bytes
       OR reconstructed_digest IS DISTINCT FROM accepted.manifest_digest THEN
        RAISE EXCEPTION 'Accepted artifact integrity failure'
            USING ERRCODE='P0018',DETAIL='INTEGRITY_FAILURE';
    END IF;

    IF p_ml_connection_id IS DISTINCT FROM p_mercado_livre_connection_id
       OR p_decision_omie_connection_id IS DISTINCT FROM p_omie_connection_id
       OR p_decision_source_order_reference IS DISTINCT FROM p_source_order_reference
       OR p_decision_marketplace_order_id IS DISTINCT FROM p_marketplace_order_id
       OR p_decision_permission IS DISTINCT FROM p_permission
       OR p_permission IS DISTINCT FROM 'TRANSACTION_IDENTITY_DECISION_WRITE'
       OR p_decision_provenance IS DISTINCT FROM p_provenance
       OR p_decision_correlation_id IS DISTINCT FROM p_correlation_id
       OR current_principal.mercado_livre_connection_id IS DISTINCT FROM p_mercado_livre_connection_id
       OR current_principal.omie_connection_id IS DISTINCT FROM p_omie_connection_id THEN
        RAISE EXCEPTION 'Decision claim scope mismatch'
            USING ERRCODE='P0017',DETAIL='SCOPE_MISMATCH';
    END IF;

    IF p_kind IS DISTINCT FROM 'CONFIRMED'
       OR p_decision_reason IS DISTINCT FROM 'EXPLICIT_CONFIRMATION'
       OR p_revision IS DISTINCT FROM 1
       OR p_supersedes_decision_id IS NOT NULL THEN
        RAISE EXCEPTION 'Unsupported attested decision form'
            USING ERRCODE='P0018',DETAIL='UNSUPPORTED_CANONICAL_FORM';
    END IF;

    PERFORM public.transaction_identity_locks(
        p_organization_id,
        p_principal_id,
        p_decision_id,
        p_decision_omie_connection_id,
        p_decision_source_order_reference,
        p_decision_marketplace_order_id
    );

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            's2a-attestation/manifest/1:' || p_organization_id || ':' ||
                linked_operation.attestation_manifest_id,
            0
        )
    );

    SELECT *
      INTO snapshot
      FROM public.s2a_v042_revalidate_snapshot(
        p_organization_id,
        linked_operation.attestation_manifest_id,
        p_schema_version,
        p_claim_manifest_id,
        p_claim_organization_id,
        p_mercado_livre_connection_id,
        p_omie_connection_id,
        p_source_order_reference,
        p_integration_reference,
        p_marketplace_order_id,
        p_permission,
        p_accountable_operator,
        p_approval_source,
        p_approval_window_start,
        p_approval_window_end,
        p_revocation_owner,
        p_credential_custodian,
        p_credential_delivery_method,
        p_credential_rotation_owner,
        p_immediate_revocation_policy,
        p_reason,
        p_provenance,
        p_correlation_id,
        p_evidence_binding_fingerprint,
        p_expected_artifact_version,
        p_expected_canonicalization_version,
        p_expected_canonical_manifest_bytes,
        p_expected_manifest_digest,
        p_expected_signature_preimage_bytes,
        p_expected_algorithm_id,
        p_expected_signer_subject_id,
        p_expected_signer_key_id,
        p_expected_signer_key_revision,
        p_expected_signer_key_fingerprint,
        p_expected_signer_key_lineage_fingerprint,
        p_expected_subject_public_key_info_der,
        p_expected_signature_bytes,
        p_expected_signer_authority_id,
        p_expected_signer_authority_revision,
        p_expected_signer_authority_fingerprint,
        p_expected_verified_at,
        p_expected_accepted_proof_fingerprint,
        p_expected_evidence_binding_fingerprint
    );

    IF snapshot.result_artifact_version IS DISTINCT FROM p_expected_artifact_version
       OR snapshot.result_canonicalization_version IS DISTINCT FROM p_expected_canonicalization_version
       OR snapshot.result_canonical_manifest_bytes IS DISTINCT FROM p_expected_canonical_manifest_bytes
       OR snapshot.result_manifest_digest IS DISTINCT FROM p_expected_manifest_digest
       OR snapshot.result_signature_preimage_bytes IS DISTINCT FROM p_expected_signature_preimage_bytes
       OR snapshot.result_algorithm_id IS DISTINCT FROM p_expected_algorithm_id
       OR snapshot.result_signer_subject_id IS DISTINCT FROM p_expected_signer_subject_id
       OR snapshot.result_signer_key_id IS DISTINCT FROM p_expected_signer_key_id
       OR snapshot.result_signer_key_revision IS DISTINCT FROM p_expected_signer_key_revision
       OR snapshot.result_signer_key_fingerprint IS DISTINCT FROM p_expected_signer_key_fingerprint
       OR snapshot.result_signer_key_lineage_fingerprint IS DISTINCT FROM p_expected_signer_key_lineage_fingerprint
       OR snapshot.result_subject_public_key_info_der IS DISTINCT FROM p_expected_subject_public_key_info_der
       OR snapshot.result_signature_bytes IS DISTINCT FROM p_expected_signature_bytes
       OR snapshot.result_signer_authority_id IS DISTINCT FROM p_expected_signer_authority_id
       OR snapshot.result_signer_authority_revision IS DISTINCT FROM p_expected_signer_authority_revision
       OR snapshot.result_signer_authority_fingerprint IS DISTINCT FROM p_expected_signer_authority_fingerprint
       OR snapshot.result_verified_at IS DISTINCT FROM p_expected_verified_at
       OR snapshot.result_accepted_proof_fingerprint IS DISTINCT FROM p_expected_accepted_proof_fingerprint
       OR snapshot.result_signed_evidence_binding_fingerprint IS DISTINCT FROM p_expected_evidence_binding_fingerprint THEN
        RAISE EXCEPTION 'Immutable snapshot mismatch'
            USING ERRCODE='P0018',DETAIL='SNAPSHOT_MISMATCH';
    END IF;

    observed_effect_time := pg_catalog.clock_timestamp()::timestamptz(6);

    SELECT o.status
      INTO observed_organization_status
      FROM public.integration_organization o
     WHERE o.organization_id=p_organization_id
     FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Governance unavailable'
            USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE';
    END IF;

    IF observed_organization_status IS DISTINCT FROM 'ACTIVE'
       OR observed_effect_time<p_approval_window_start
       OR observed_effect_time>=p_approval_window_end THEN
        RAISE EXCEPTION 'Current approval eligibility denied'
            USING ERRCODE='P0017',DETAIL='EXPIRED_OR_NOT_YET_VALID';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            's2a-governance/signer-key/1:' || p_organization_id || ':' ||
                snapshot.result_signer_key_id,
            0
        )
    );

    SELECT count(*)
      INTO key_leaf_count
      FROM public.s2a_signer_key_revision k
     WHERE k.organization_id=p_organization_id
       AND k.signer_key_id=snapshot.result_signer_key_id
       AND NOT EXISTS (
            SELECT 1
              FROM public.s2a_signer_key_revision successor
             WHERE successor.organization_id=k.organization_id
               AND successor.signer_key_id=k.signer_key_id
               AND successor.supersedes_revision=k.revision
       );

    IF key_leaf_count<>1 THEN
        RAISE EXCEPTION 'Signer key lineage conflict'
            USING ERRCODE='P0016',DETAIL='GOVERNANCE_CONFLICT';
    END IF;

    SELECT k.*
      INTO effective_key
      FROM public.s2a_signer_key_revision k
     WHERE k.organization_id=p_organization_id
       AND k.signer_key_id=snapshot.result_signer_key_id
       AND k.effective_at<=observed_effect_time
     ORDER BY k.effective_at DESC,k.revision DESC
     LIMIT 1;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Signer key unavailable'
            USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE';
    END IF;

    IF effective_key.valid_from>observed_effect_time
       OR effective_key.state IS DISTINCT FROM 'ACTIVE' THEN
        RAISE EXCEPTION 'Signer key ineligible'
            USING ERRCODE='P0017',DETAIL='EXPIRED_OR_NOT_YET_VALID';
    END IF;

    IF effective_key.signer_subject_id IS DISTINCT FROM snapshot.result_signer_subject_id
       OR effective_key.algorithm_id IS DISTINCT FROM snapshot.result_algorithm_id
       OR effective_key.subject_public_key_info_der IS DISTINCT FROM snapshot.result_subject_public_key_info_der
       OR effective_key.signer_key_fingerprint IS DISTINCT FROM snapshot.result_signer_key_fingerprint THEN
        RAISE EXCEPTION 'Signer key scope mismatch'
            USING ERRCODE='P0017',DETAIL='SCOPE_MISMATCH';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            's2a-governance/signer-authority-scope/1:' || p_organization_id || ':' ||
            snapshot.result_signer_subject_id || ':' || snapshot.result_signer_key_id ||
            ':S2A_FIELD_PROOF_APPROVAL:TRANSACTION_IDENTITY_DECISION_WRITE',
            0
        )
    );

    SELECT count(*)
      INTO authority_leaf_count
      FROM public.s2a_signer_authority_revision a
     WHERE a.organization_id=p_organization_id
       AND a.signer_subject_id=snapshot.result_signer_subject_id
       AND a.signer_key_id=snapshot.result_signer_key_id
       AND a.approval_action='S2A_FIELD_PROOF_APPROVAL'
       AND a.permission='TRANSACTION_IDENTITY_DECISION_WRITE'
       AND NOT EXISTS (
            SELECT 1
              FROM public.s2a_signer_authority_revision successor
             WHERE successor.organization_id=a.organization_id
               AND successor.supersedes_signer_authority_id=a.signer_authority_id
       );

    IF authority_leaf_count=0 THEN
        RAISE EXCEPTION 'Signer authority unavailable'
            USING ERRCODE='P0015',DETAIL='GOVERNANCE_UNAVAILABLE';
    ELSIF authority_leaf_count<>1 THEN
        RAISE EXCEPTION 'Signer authority conflict'
            USING ERRCODE='P0016',DETAIL='GOVERNANCE_CONFLICT';
    END IF;

    SELECT a.*
      INTO STRICT current_authority
      FROM public.s2a_signer_authority_revision a
     WHERE a.organization_id=p_organization_id
       AND a.signer_subject_id=snapshot.result_signer_subject_id
       AND a.signer_key_id=snapshot.result_signer_key_id
       AND a.approval_action='S2A_FIELD_PROOF_APPROVAL'
       AND a.permission='TRANSACTION_IDENTITY_DECISION_WRITE'
       AND NOT EXISTS (
            SELECT 1
              FROM public.s2a_signer_authority_revision successor
             WHERE successor.organization_id=a.organization_id
               AND successor.supersedes_signer_authority_id=a.signer_authority_id
       );

    IF current_authority.signer_key_revision IS DISTINCT FROM effective_key.revision
       OR current_authority.signer_key_fingerprint IS DISTINCT FROM effective_key.signer_key_fingerprint THEN
        RAISE EXCEPTION 'Signer authority key scope mismatch'
            USING ERRCODE='P0017',DETAIL='SCOPE_MISMATCH';
    END IF;

    IF current_authority.state IS DISTINCT FROM 'ENABLED'
       OR current_authority.valid_from>observed_effect_time
       OR observed_effect_time>=current_authority.valid_until THEN
        RAISE EXCEPTION 'Signer authority ineligible'
            USING ERRCODE='P0017',DETAIL='EXPIRED_OR_NOT_YET_VALID';
    END IF;

    current_evidence := public.s2a_v041_evidence_fingerprint(
        p_organization_id,
        p_marketplace_order_id,
        p_mercado_livre_connection_id,
        p_omie_connection_id,
        p_source_order_reference,
        p_integration_reference
    );

    IF current_evidence IS DISTINCT FROM snapshot.result_signed_evidence_binding_fingerprint THEN
        RAISE EXCEPTION 'Evidence scope mismatch'
            USING ERRCODE='P0017',DETAIL='SCOPE_MISMATCH';
    END IF;

    SELECT count(*)
      INTO prior_action_count
      FROM public.marketplace_transaction_identity_decision d
     WHERE d.organization_id=p_organization_id
       AND d.grant_id=p_grant_id;

    IF prior_action_count>0 THEN
        RAISE EXCEPTION 'Linked grant action already consumed'
            USING ERRCODE='P0018',DETAIL='SINGLE_ACTION_CONSUMED';
    END IF;

    INSERT INTO public.marketplace_transaction_identity_decision(
        organization_id,
        decision_id,
        omie_connection_id,
        source_order_reference,
        marketplace_order_id,
        kind,
        reason,
        revision,
        supersedes_decision_id,
        ml_connection_id,
        ml_capability,
        ml_progress_version,
        ml_record_ordinal,
        external_order_id,
        currency,
        omie_capability,
        omie_progress_version,
        omie_record_ordinal,
        omie_semantic_fingerprint,
        provider_revision_local,
        principal_id,
        credential_id,
        credential_revision,
        grant_id,
        grant_revision,
        permission,
        authorization_semantic_version,
        authorization_fingerprint,
        intent_fingerprint,
        decision_semantic_fingerprint,
        provenance,
        correlation_id
    )
    VALUES (
        p_organization_id,
        p_decision_id,
        p_decision_omie_connection_id,
        p_decision_source_order_reference,
        p_decision_marketplace_order_id,
        p_kind,
        p_decision_reason,
        p_revision,
        p_supersedes_decision_id,
        p_ml_connection_id,
        p_ml_capability,
        p_ml_progress_version,
        p_ml_record_ordinal,
        p_external_order_id,
        p_currency,
        p_omie_capability,
        p_omie_progress_version,
        p_omie_record_ordinal,
        p_omie_semantic_fingerprint,
        p_provider_revision_local,
        p_principal_id,
        p_credential_id,
        p_credential_revision,
        p_grant_id,
        p_grant_revision,
        p_decision_permission,
        p_authorization_semantic_version,
        p_authorization_fingerprint,
        p_intent_fingerprint,
        p_decision_semantic_fingerprint,
        p_decision_provenance,
        p_decision_correlation_id
    )
    RETURNING * INTO persisted;

    RETURN QUERY
    SELECT
        'APPLIED'::text,
        persisted.decision_id,
        persisted.decision_semantic_fingerprint::text,
        persisted.decided_at;
END;

BEGIN
    IF TG_OP<>'INSERT' OR TG_TABLE_SCHEMA<>'public'
       OR TG_TABLE_NAME<>'offline_expected_signed_attestation' THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Original binding input is immutable';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.offline_binding_header h
                   WHERE h.binding_id=NEW.binding_id
                     AND pg_catalog.encode(h.manifest_digest,'hex')=NEW.manifest_digest)
       OR NEW.canonical_expected_attestation IS DISTINCT FROM pg_catalog.int4send(pg_catalog.octet_length(pg_catalog.convert_to('FLOOOW/OFFLINE-FIELD-PROOF/EXPECTED-SIGNED-ATTESTATION/V1','UTF8')))||pg_catalog.convert_to('FLOOOW/OFFLINE-FIELD-PROOF/EXPECTED-SIGNED-ATTESTATION/V1','UTF8')||pg_catalog.int2send(6::pg_catalog.int2)||pg_catalog.int2send(1::pg_catalog.int2)||pg_catalog.int4send(1+pg_catalog.octet_length(pg_catalog.uuid_send(NEW.binding_id)))||pg_catalog.decode('01','hex')||pg_catalog.uuid_send(NEW.binding_id)||pg_catalog.int2send(2::pg_catalog.int2)||pg_catalog.int4send(1+pg_catalog.octet_length(pg_catalog.convert_to(NEW.manifest_digest,'UTF8')))||pg_catalog.decode('01','hex')||pg_catalog.convert_to(NEW.manifest_digest,'UTF8')||pg_catalog.int2send(3::pg_catalog.int2)||pg_catalog.int4send(1+pg_catalog.octet_length(pg_catalog.convert_to(NEW.algorithm_id,'UTF8')))||pg_catalog.decode('01','hex')||pg_catalog.convert_to(NEW.algorithm_id,'UTF8')||pg_catalog.int2send(4::pg_catalog.int2)||pg_catalog.int4send(1+pg_catalog.octet_length(pg_catalog.uuid_send(NEW.signer_key_id)))||pg_catalog.decode('01','hex')||pg_catalog.uuid_send(NEW.signer_key_id)||pg_catalog.int2send(5::pg_catalog.int2)||pg_catalog.int4send(1+pg_catalog.octet_length(pg_catalog.convert_to(NEW.signer_key_fingerprint,'UTF8')))||pg_catalog.decode('01','hex')||pg_catalog.convert_to(NEW.signer_key_fingerprint,'UTF8')||pg_catalog.int2send(6::pg_catalog.int2)||pg_catalog.int4send(1+pg_catalog.octet_length(NEW.signature_bytes))||pg_catalog.decode('01','hex')||NEW.signature_bytes THEN
        RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid original signed-attestation commitment';
    END IF;
    RETURN NEW;
END;

DECLARE
    header_record record;
    ready_record record;
    policy_record record;
    attempt_record record;
    execution_record record;
    pointer_record record;
    caller_record record;
    slot_cursor pg_catalog.int4;
    slot_length pg_catalog.int8;
    slot_oid pg_catalog.int8;
    slot_name_length pg_catalog.int8;
    slot_name pg_catalog.text;
    slot_oids pg_catalog.int8[] := ARRAY[]::pg_catalog.int8[];
    slot_names pg_catalog.text[] := ARRAY[]::pg_catalog.text[];
    slot_number pg_catalog.int4;
    field_tag pg_catalog.int4;
    byte_number pg_catalog.int4;
    cursor_position pg_catalog.int4;
    payload_length pg_catalog.int8;
    domain_length pg_catalog.int8;
    field_value pg_catalog.numeric;
    policy_values pg_catalog.int8[] := ARRAY[]::pg_catalog.int8[];
    database_now pg_catalog.timestamptz;
    principal_found pg_catalog.uuid;
BEGIN
    IF $1 IS NULL OR $2 IS NULL OR $3 IS NULL OR $4 IS NULL OR $5 IS NULL
       OR $6 IS NULL OR $7 IS NULL OR $8 IS NULL OR $9 IS NULL
       OR $1 = '00000000-0000-0000-0000-000000000000'::pg_catalog.uuid
       OR $3 = '00000000-0000-0000-0000-000000000000'::pg_catalog.uuid
       OR $5 = '00000000-0000-0000-0000-000000000000'::pg_catalog.uuid
       OR $7 = '00000000-0000-0000-0000-000000000000'::pg_catalog.uuid
       OR $8 = '00000000-0000-0000-0000-000000000000'::pg_catalog.uuid
       OR pg_catalog.octet_length($2) <> 32 OR pg_catalog.octet_length($9) <> 32
       OR $4 <> '0090-v1' OR $6 <= 0
       OR pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    SELECT h.binding_id,h.deployment_id,h.deployment_incarnation_id,h.identity_slots,
           h.offline_surface_version,h.deadline_policy_version,h.deadline_policy_digest,
           h.plan_fingerprint,h.organization_id,h.principal_id,
           h.mercado_livre_connection_id,h.omie_connection_id,h.valid_from,h.expires_at
      INTO header_record FROM public.offline_binding_header h
     WHERE h.binding_id=$1 AND h.plan_fingerprint=$2
       AND h.deployment_incarnation_id=$3 AND h.offline_surface_version=$4;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED'; END IF;
    -- Decode exact canonical slots; use session_user, never current_user or a caller OID.
    IF pg_catalog.octet_length(header_record.identity_slots) < 4
       OR pg_catalog.substring(header_record.identity_slots,1,4) <> '\x00000004'::pg_catalog.bytea THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    slot_cursor := 4;
    FOR slot_number IN 1..4 LOOP
        slot_length := 0;
        FOR byte_number IN 0..3 LOOP
            slot_length := slot_length*256 + pg_catalog.get_byte(header_record.identity_slots,slot_cursor+byte_number);
        END LOOP;
        slot_cursor := slot_cursor+4;
        IF slot_length < 10 OR slot_length > pg_catalog.octet_length(header_record.identity_slots)-slot_cursor
           OR pg_catalog.get_byte(header_record.identity_slots,slot_cursor) <> slot_number THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        slot_oid := 0; slot_name_length := 0;
        FOR byte_number IN 0..3 LOOP
            slot_oid := slot_oid*256+pg_catalog.get_byte(header_record.identity_slots,slot_cursor+1+byte_number);
            slot_name_length := slot_name_length*256+pg_catalog.get_byte(header_record.identity_slots,slot_cursor+5+byte_number);
        END LOOP;
        IF slot_oid=0 OR slot_name_length <> slot_length-9 OR slot_oid=ANY(slot_oids) THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        slot_name := pg_catalog.convert_from(pg_catalog.substring(header_record.identity_slots,
                      slot_cursor+10,slot_name_length::pg_catalog.int4),'UTF8');
        IF slot_name IS NOT NFC NORMALIZED OR slot_name=ANY(slot_names) THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        SELECT r.oid,r.rolname,r.rolcanlogin,r.rolinherit,r.rolsuper,r.rolcreaterole,
               r.rolcreatedb,r.rolreplication,r.rolbypassrls
          INTO caller_record FROM pg_catalog.pg_roles r WHERE r.oid::pg_catalog.int8=slot_oid AND r.rolname=slot_name;
        IF NOT FOUND OR NOT caller_record.rolcanlogin OR caller_record.rolinherit
           OR caller_record.rolsuper OR caller_record.rolcreaterole OR caller_record.rolcreatedb
           OR caller_record.rolreplication OR caller_record.rolbypassrls
           OR EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members m
                      WHERE m.member=caller_record.oid OR m.roleid=caller_record.oid) THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        IF slot_number=3 AND slot_name <> SESSION_USER THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        slot_oids := pg_catalog.array_append(slot_oids,slot_oid);
        slot_names := pg_catalog.array_append(slot_names,slot_name);
        slot_cursor := slot_cursor+slot_length::pg_catalog.int4;
    END LOOP;
    IF slot_cursor <> pg_catalog.octet_length(header_record.identity_slots) THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    SELECT p.policy_version,p.policy_digest,p.canonical_policy,p.effective_from INTO policy_record
      FROM public.offline_deadline_policy p
     WHERE p.policy_version=header_record.deadline_policy_version AND p.policy_digest=header_record.deadline_policy_digest;
    IF NOT FOUND OR pg_catalog.sha256(policy_record.canonical_policy) <> policy_record.policy_digest THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    -- Full29-field parser, with checked signed-int8 conversion; no TTL/GUC/default source.
    domain_length := 0;
    FOR byte_number IN 0..3 LOOP
        domain_length := domain_length*256+pg_catalog.get_byte(policy_record.canonical_policy,byte_number);
    END LOOP;
    IF domain_length <> pg_catalog.octet_length(pg_catalog.convert_to('FLOOOW/OFFLINE-FIELD-PROOF/DEADLINE-POLICY/V1','UTF8'))
       OR pg_catalog.substring(policy_record.canonical_policy,5,domain_length::pg_catalog.int4)
           <> pg_catalog.convert_to('FLOOOW/OFFLINE-FIELD-PROOF/DEADLINE-POLICY/V1','UTF8') THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    cursor_position := domain_length::pg_catalog.int4+4;
    IF pg_catalog.get_byte(policy_record.canonical_policy,cursor_position) <> 0
       OR pg_catalog.get_byte(policy_record.canonical_policy,cursor_position+1) <> 29 THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    cursor_position := cursor_position+2;
    FOR field_tag IN 1..29 LOOP
        IF pg_catalog.get_byte(policy_record.canonical_policy,cursor_position) <> 0
           OR pg_catalog.get_byte(policy_record.canonical_policy,cursor_position+1) <> field_tag THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        payload_length := 0;
        FOR byte_number IN 0..3 LOOP
            payload_length := payload_length*256+pg_catalog.get_byte(policy_record.canonical_policy,cursor_position+2+byte_number);
        END LOOP;
        IF payload_length <= 1 OR payload_length > pg_catalog.octet_length(policy_record.canonical_policy)-cursor_position-6
           OR pg_catalog.get_byte(policy_record.canonical_policy,cursor_position+6) <> 1 THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        IF field_tag=1 THEN
            IF pg_catalog.substring(policy_record.canonical_policy,cursor_position+8,(payload_length-1)::pg_catalog.int4)
               <> pg_catalog.convert_to(policy_record.policy_version,'UTF8')
               OR policy_record.policy_version='' OR policy_record.policy_version IS NOT NFC NORMALIZED THEN
                RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
            END IF;
        ELSE
            IF payload_length <> 9 THEN RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED'; END IF;
            field_value := 0;
            FOR byte_number IN 0..7 LOOP
                field_value := field_value*256+pg_catalog.get_byte(policy_record.canonical_policy,cursor_position+7+byte_number);
            END LOOP;
            IF field_value <= 0 OR field_value > 9223372036854775807 THEN
                RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
            END IF;
            policy_values := pg_catalog.array_append(policy_values,field_value::pg_catalog.int8);
        END IF;
        cursor_position := cursor_position+6+payload_length::pg_catalog.int4;
    END LOOP;
    IF cursor_position <> pg_catalog.octet_length(policy_record.canonical_policy) THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    FOR field_tag IN 1..14 LOOP
        IF policy_values[field_tag*2-1] > policy_values[field_tag*2] THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
    END LOOP;
    IF policy_values[3] > policy_values[2] OR policy_values[5] > policy_values[2]
       OR policy_values[7] > policy_values[2] OR policy_values[9] > policy_values[13]
       OR policy_values[11] > policy_values[13]
       OR policy_values[15] > LEAST(policy_values[9],policy_values[11],policy_values[13])
       OR policy_values[17] > LEAST(policy_values[11],policy_values[13])
       OR policy_values[25] >= policy_values[17] THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    SELECT r.deployment_id,r.incarnation_id,r.state,r.policy_version,r.policy_digest,
           r.watchdog_checked_at,r.watchdog_healthy INTO ready_record
      FROM public.offline_readiness r WHERE r.deployment_id=header_record.deployment_id AND r.incarnation_id=$3;
    IF NOT FOUND OR ready_record.state <> 'READY' OR ready_record.policy_version <> policy_record.policy_version
       OR ready_record.policy_digest <> policy_record.policy_digest OR NOT ready_record.watchdog_healthy THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    -- C: lifecycle -> pointer -> attempt -> execution, before the private domain lock.
    PERFORM l.binding_id FROM public.offline_binding_lifecycle l WHERE l.binding_id=$1 AND l.state='ACTIVE' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED'; END IF;
    SELECT p.binding_id,p.current_attempt_id,p.generation INTO pointer_record
      FROM public.offline_attempt_pointer p WHERE p.binding_id=$1 FOR UPDATE;
    IF NOT FOUND OR pointer_record.current_attempt_id IS DISTINCT FROM $5 OR pointer_record.generation <> $6 THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    SELECT a.binding_id,a.attempt_id,a.generation,a.state,a.claimed_at,a.expires_at INTO attempt_record
      FROM public.offline_attempt a WHERE a.binding_id=$1 AND a.attempt_id=$5 AND a.generation=$6 FOR UPDATE;
    IF NOT FOUND OR attempt_record.state <> 'EFFECTS_IN_PROGRESS' THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    SELECT e.binding_id,e.attempt_id,e.generation,e.execution_id,e.instance_id,e.executor_oid,
           e.state,e.claimed_at,e.expires_at,e.possession_digest INTO execution_record
      FROM public.offline_execution e WHERE e.binding_id=$1 AND e.attempt_id=$5 AND e.generation=$6
       AND e.execution_id=$7 AND e.instance_id=$8 FOR UPDATE;
    IF NOT FOUND OR execution_record.state <> 'OWNED' OR execution_record.executor_oid <> slot_oids[3]
       OR execution_record.possession_digest <> pg_catalog.sha256($9) THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    PERFORM d.binding_id FROM public.offline_delivery d WHERE d.binding_id=$1 AND d.attempt_id=$5 AND d.generation=$6
       AND d.execution_id=$7 AND d.instance_id=$8 AND d.state='DELIVERY_ACKNOWLEDGED';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED'; END IF;
    PERFORM r.binding_id FROM public.offline_reconciliation r WHERE r.binding_id=$1 AND r.state='NOT_STARTED';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED'; END IF;
    PERFORM c.binding_id FROM public.offline_ceremony_result c WHERE c.binding_id=$1 AND c.result='NONE';
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED'; END IF;
    database_now := pg_catalog.clock_timestamp();
    IF NOT pg_catalog.isfinite(database_now) OR NOT pg_catalog.isfinite(policy_record.effective_from)
       OR NOT pg_catalog.isfinite(ready_record.watchdog_checked_at)
       OR database_now < policy_record.effective_from OR database_now < header_record.valid_from
       OR database_now >= header_record.expires_at OR database_now < attempt_record.claimed_at
       OR database_now >= attempt_record.expires_at OR database_now < execution_record.claimed_at
       OR database_now >= execution_record.expires_at OR database_now < ready_record.watchdog_checked_at
       OR EXTRACT(EPOCH FROM(database_now-ready_record.watchdog_checked_at))*1000000 > policy_values[23]
       OR EXTRACT(EPOCH FROM(database_now-pg_catalog.transaction_timestamp()))*1000000 > policy_values[1] THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    IF NOT public.command_authorization_organization_lock(header_record.organization_id::pg_catalog.uuid) THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    SELECT p.principal_id INTO principal_found FROM public.command_principal p
     WHERE p.organization_id=header_record.organization_id AND p.principal_id=header_record.principal_id
       AND p.mercado_livre_connection_id=header_record.mercado_livre_connection_id
       AND p.omie_connection_id=header_record.omie_connection_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED'; END IF;
    -- Re-read wall clock after blocking locks; a successful lock never renews a deadline.
    SELECT r.deployment_id,r.incarnation_id,r.state,r.policy_version,r.policy_digest,
           r.watchdog_checked_at,r.watchdog_healthy INTO ready_record
      FROM public.offline_readiness r WHERE r.deployment_id=header_record.deployment_id AND r.incarnation_id=$3;
    IF NOT FOUND OR ready_record.state <> 'READY' OR ready_record.policy_version <> policy_record.policy_version
       OR ready_record.policy_digest <> policy_record.policy_digest OR NOT ready_record.watchdog_healthy THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    database_now := pg_catalog.clock_timestamp();
    IF database_now >= header_record.expires_at OR database_now >= attempt_record.expires_at
       OR database_now >= execution_record.expires_at
       OR NOT pg_catalog.isfinite(ready_record.watchdog_checked_at) OR database_now < ready_record.watchdog_checked_at
       OR EXTRACT(EPOCH FROM(database_now-ready_record.watchdog_checked_at))*1000000 > policy_values[23]
       OR EXTRACT(EPOCH FROM(database_now-pg_catalog.transaction_timestamp()))*1000000 > policy_values[1] THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    RETURN TRUE;
EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
END;

DECLARE
    header_record record;
    ready_record record;
    policy_record record;
    caller_record record;
    slot_cursor pg_catalog.int4;
    slot_length pg_catalog.int8;
    slot_oid pg_catalog.int8;
    slot_name_length pg_catalog.int8;
    slot_name pg_catalog.text;
    slot_oids pg_catalog.int8[] := ARRAY[]::pg_catalog.int8[];
    slot_names pg_catalog.text[] := ARRAY[]::pg_catalog.text[];
    slot_number pg_catalog.int4;
    field_tag pg_catalog.int4;
    byte_number pg_catalog.int4;
    cursor_position pg_catalog.int4;
    payload_length pg_catalog.int8;
    domain_length pg_catalog.int8;
    field_value pg_catalog.numeric;
    policy_values pg_catalog.int8[] := ARRAY[]::pg_catalog.int8[];
    database_now pg_catalog.timestamptz;
BEGIN
    IF $1 IS NULL OR $2 IS NULL OR $3 IS NULL OR $4 IS NULL
       OR $1='00000000-0000-0000-0000-000000000000'::pg_catalog.uuid
       OR $3='00000000-0000-0000-0000-000000000000'::pg_catalog.uuid
       OR pg_catalog.octet_length($2)<>32 OR $4<>'0090-v1'
       OR pg_catalog.current_setting('transaction_isolation')<>'repeatable read'
       OR pg_catalog.current_setting('transaction_read_only')<>'on' THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    SELECT h.binding_id,h.deployment_id,h.deployment_incarnation_id,h.identity_slots,
           h.offline_surface_version,h.deadline_policy_version,h.deadline_policy_digest,
           h.plan_fingerprint,h.organization_id,h.manifest_id,h.principal_id,
           h.credential_id,h.grant_id,h.principal_operation_id,h.credential_operation_id,
           h.grant_operation_id,h.mercado_livre_connection_id,h.omie_connection_id,
           h.reason,h.provenance,h.correlation_id
      INTO header_record FROM public.offline_binding_header h
     WHERE h.binding_id=$1 AND h.plan_fingerprint=$2
       AND h.deployment_incarnation_id=$3 AND h.offline_surface_version=$4;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED'; END IF;
    -- Decode exact canonical slots; use session_user, never current_user or a caller OID.
    IF pg_catalog.octet_length(header_record.identity_slots) < 4
       OR pg_catalog.substring(header_record.identity_slots,1,4) <> '\x00000004'::pg_catalog.bytea THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    slot_cursor := 4;
    FOR slot_number IN 1..4 LOOP
        slot_length := 0;
        FOR byte_number IN 0..3 LOOP
            slot_length := slot_length*256 + pg_catalog.get_byte(header_record.identity_slots,slot_cursor+byte_number);
        END LOOP;
        slot_cursor := slot_cursor+4;
        IF slot_length < 10 OR slot_length > pg_catalog.octet_length(header_record.identity_slots)-slot_cursor
           OR pg_catalog.get_byte(header_record.identity_slots,slot_cursor) <> slot_number THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        slot_oid := 0; slot_name_length := 0;
        FOR byte_number IN 0..3 LOOP
            slot_oid := slot_oid*256+pg_catalog.get_byte(header_record.identity_slots,slot_cursor+1+byte_number);
            slot_name_length := slot_name_length*256+pg_catalog.get_byte(header_record.identity_slots,slot_cursor+5+byte_number);
        END LOOP;
        IF slot_oid=0 OR slot_name_length <> slot_length-9 OR slot_oid=ANY(slot_oids) THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        slot_name := pg_catalog.convert_from(pg_catalog.substring(header_record.identity_slots,
                      slot_cursor+10,slot_name_length::pg_catalog.int4),'UTF8');
        IF slot_name IS NOT NFC NORMALIZED OR slot_name=ANY(slot_names) THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        SELECT r.oid,r.rolname,r.rolcanlogin,r.rolinherit,r.rolsuper,r.rolcreaterole,
               r.rolcreatedb,r.rolreplication,r.rolbypassrls
          INTO caller_record FROM pg_catalog.pg_roles r WHERE r.oid::pg_catalog.int8=slot_oid AND r.rolname=slot_name;
        IF NOT FOUND OR NOT caller_record.rolcanlogin OR caller_record.rolinherit
           OR caller_record.rolsuper OR caller_record.rolcreaterole OR caller_record.rolcreatedb
           OR caller_record.rolreplication OR caller_record.rolbypassrls
           OR EXISTS(SELECT 1 FROM pg_catalog.pg_auth_members m
                      WHERE m.member=caller_record.oid OR m.roleid=caller_record.oid) THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        IF slot_number=4 AND slot_name <> SESSION_USER THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        slot_oids := pg_catalog.array_append(slot_oids,slot_oid);
        slot_names := pg_catalog.array_append(slot_names,slot_name);
        slot_cursor := slot_cursor+slot_length::pg_catalog.int4;
    END LOOP;
    IF slot_cursor <> pg_catalog.octet_length(header_record.identity_slots) THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    SELECT p.policy_version,p.policy_digest,p.canonical_policy,p.effective_from INTO policy_record
      FROM public.offline_deadline_policy p
     WHERE p.policy_version=header_record.deadline_policy_version AND p.policy_digest=header_record.deadline_policy_digest;
    IF NOT FOUND OR pg_catalog.sha256(policy_record.canonical_policy) <> policy_record.policy_digest THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    -- Full29-field parser, with checked signed-int8 conversion; no TTL/GUC/default source.
    domain_length := 0;
    FOR byte_number IN 0..3 LOOP
        domain_length := domain_length*256+pg_catalog.get_byte(policy_record.canonical_policy,byte_number);
    END LOOP;
    IF domain_length <> pg_catalog.octet_length(pg_catalog.convert_to('FLOOOW/OFFLINE-FIELD-PROOF/DEADLINE-POLICY/V1','UTF8'))
       OR pg_catalog.substring(policy_record.canonical_policy,5,domain_length::pg_catalog.int4)
           <> pg_catalog.convert_to('FLOOOW/OFFLINE-FIELD-PROOF/DEADLINE-POLICY/V1','UTF8') THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    cursor_position := domain_length::pg_catalog.int4+4;
    IF pg_catalog.get_byte(policy_record.canonical_policy,cursor_position) <> 0
       OR pg_catalog.get_byte(policy_record.canonical_policy,cursor_position+1) <> 29 THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    cursor_position := cursor_position+2;
    FOR field_tag IN 1..29 LOOP
        IF pg_catalog.get_byte(policy_record.canonical_policy,cursor_position) <> 0
           OR pg_catalog.get_byte(policy_record.canonical_policy,cursor_position+1) <> field_tag THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        payload_length := 0;
        FOR byte_number IN 0..3 LOOP
            payload_length := payload_length*256+pg_catalog.get_byte(policy_record.canonical_policy,cursor_position+2+byte_number);
        END LOOP;
        IF payload_length <= 1 OR payload_length > pg_catalog.octet_length(policy_record.canonical_policy)-cursor_position-6
           OR pg_catalog.get_byte(policy_record.canonical_policy,cursor_position+6) <> 1 THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
        IF field_tag=1 THEN
            IF pg_catalog.substring(policy_record.canonical_policy,cursor_position+8,(payload_length-1)::pg_catalog.int4)
               <> pg_catalog.convert_to(policy_record.policy_version,'UTF8')
               OR policy_record.policy_version='' OR policy_record.policy_version IS NOT NFC NORMALIZED THEN
                RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
            END IF;
        ELSE
            IF payload_length <> 9 THEN RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED'; END IF;
            field_value := 0;
            FOR byte_number IN 0..7 LOOP
                field_value := field_value*256+pg_catalog.get_byte(policy_record.canonical_policy,cursor_position+7+byte_number);
            END LOOP;
            IF field_value <= 0 OR field_value > 9223372036854775807 THEN
                RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
            END IF;
            policy_values := pg_catalog.array_append(policy_values,field_value::pg_catalog.int8);
        END IF;
        cursor_position := cursor_position+6+payload_length::pg_catalog.int4;
    END LOOP;
    IF cursor_position <> pg_catalog.octet_length(policy_record.canonical_policy) THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    FOR field_tag IN 1..14 LOOP
        IF policy_values[field_tag*2-1] > policy_values[field_tag*2] THEN
            RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
        END IF;
    END LOOP;
    IF policy_values[3] > policy_values[2] OR policy_values[5] > policy_values[2]
       OR policy_values[7] > policy_values[2] OR policy_values[9] > policy_values[13]
       OR policy_values[11] > policy_values[13]
       OR policy_values[15] > LEAST(policy_values[9],policy_values[11],policy_values[13])
       OR policy_values[17] > LEAST(policy_values[11],policy_values[13])
       OR policy_values[25] >= policy_values[17] THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    SELECT r.deployment_id,r.incarnation_id,r.state,r.policy_version,r.policy_digest,
           r.watchdog_checked_at,r.watchdog_healthy INTO ready_record
      FROM public.offline_readiness r WHERE r.deployment_id=header_record.deployment_id AND r.incarnation_id=$3;
    IF NOT FOUND OR ready_record.state <> 'READY' OR ready_record.policy_version <> policy_record.policy_version
       OR ready_record.policy_digest <> policy_record.policy_digest OR NOT ready_record.watchdog_healthy THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    database_now := pg_catalog.clock_timestamp();
    IF NOT pg_catalog.isfinite(database_now) OR NOT pg_catalog.isfinite(policy_record.effective_from)
       OR database_now<policy_record.effective_from
       OR NOT pg_catalog.isfinite(ready_record.watchdog_checked_at)
       OR database_now<ready_record.watchdog_checked_at
       OR EXTRACT(EPOCH FROM(database_now-ready_record.watchdog_checked_at))*1000000>policy_values[23]
       OR EXTRACT(EPOCH FROM(database_now-pg_catalog.transaction_timestamp()))*1000000>policy_values[19] THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    -- Exact canonical operations, never caller-selected IDs or a persisted match flag.
    -- Missing joins produce false; query failure is an error, never inferred absence.
    RETURN QUERY
    SELECT pg_catalog.count(*) BETWEEN 1 AND 3 AND pg_catalog.bool_and(x.intent_ok) IS TRUE,
           pg_catalog.count(*) BETWEEN 1 AND 3 AND pg_catalog.bool_and(x.receipt_ok) IS TRUE
      FROM (
        SELECT o.intent_fingerprint=public.s2a_v042_authority_intent(
                   o.operation,o.operation_id,o.organization_id,o.principal_id,
                   p.mercado_livre_connection_id,p.omie_connection_id,o.credential_id,
                   c.secret_verifier,o.grant_id,p.reason,p.provenance,o.correlation_id,
                   o.attestation_manifest_id,a.accepted_proof_fingerprint,a.manifest_digest) AS intent_ok,
               o.receipt_fingerprint=public.s2a_v042_authority_receipt(
                   o.intent_fingerprint,o.operation,o.principal_id,o.credential_id,
                   o.credential_revision,o.grant_id,o.grant_revision,o.permission,o.state) AS receipt_ok
          FROM public.command_authority_operation o
          JOIN public.command_principal p ON p.organization_id=o.organization_id AND p.principal_id=o.principal_id
          JOIN public.s2a_accepted_attestation a ON a.organization_id=o.organization_id AND a.manifest_id=o.attestation_manifest_id
          LEFT JOIN public.command_permission_grant g ON g.organization_id=o.organization_id AND g.grant_id=o.grant_id
          LEFT JOIN public.command_credential_revision c ON c.organization_id=o.organization_id
               AND c.credential_id=o.credential_id AND c.revision=o.credential_revision
         WHERE o.organization_id=header_record.organization_id
           AND o.attestation_manifest_id=header_record.manifest_id
           AND o.principal_id=header_record.principal_id
           AND p.mercado_livre_connection_id=header_record.mercado_livre_connection_id
           AND p.omie_connection_id=header_record.omie_connection_id
           AND p.reason=header_record.reason AND p.provenance=header_record.provenance
           AND o.correlation_id=header_record.correlation_id
           AND ((o.operation='PRINCIPAL' AND o.operation_id=header_record.principal_operation_id
                 AND o.decided_at=p.decided_at)
             OR (o.operation='INITIAL_CREDENTIAL' AND o.operation_id=header_record.credential_operation_id
                 AND o.credential_id=header_record.credential_id AND c.principal_id=header_record.principal_id
                 AND o.decided_at=c.decided_at)
             OR (o.operation='GRANT' AND o.operation_id=header_record.grant_operation_id
                 AND o.grant_id=header_record.grant_id AND o.credential_id IS NULL
                 AND g.principal_id=header_record.principal_id
                 AND o.decided_at=g.decided_at))
      ) x;
EXCEPTION WHEN OTHERS THEN
    IF SQLSTATE='P0017' THEN
        RAISE EXCEPTION USING ERRCODE='P0017',MESSAGE='ACCESS_DENIED';
    END IF;
    RAISE EXCEPTION USING ERRCODE='P0018',MESSAGE='INDETERMINATE';
END;

DECLARE
